const PYTHON_TARGET = import.meta.env.VITE_PYTHON_API_TARGET || ''   // 예: http://localhost:8000


const ensureAbsTarget = (t, name) => {
	const v = String(t || '').trim()
	if (!v) throw new Error(`[api] ${name} is empty (need VITE_*_API_TARGET)`)
	if (!/^https?:\/\//i.test(v)) throw new Error(`[api] ${name} must start with http:// or https:// : ${v}`)
	return v.replace(/\/+$/,'')
}

/**
 * baseURL 정책
 * - DEV: 기존 방식(상대경로) => /api, /papi  (vite proxy 전제)
 * - 그 외: 직접 호출(절대경로) => {TARGET} + {/api or /papi}
 */
export const getBaseURL = (prefix) => {

	if (prefix === SERVER_BASE) {
		//const target = ensureAbsTarget(BACKEND_TARGET, 'VITE_BACKEND_API_TARGET')
		return ensureAbsTarget(BACKEND_TARGET, 'VITE_BACKEND_API_TARGET')
	}

	if (prefix === PYTHON_BASE) {
		//const target = ensureAbsTarget(PYTHON_TARGET, 'VITE_PYTHON_API_TARGET')
		return ensureAbsTarget(PYTHON_TARGET, 'VITE_PYTHON_API_TARGET')
	}

	return prefix
}

function createInstance(prefix, paramData, params, contentType, headers, responseType) {
	const instance = axios.create({
		baseURL: getBaseURL(prefix),
		timeout,
		responseType: responseType || 'json',
		headers: headers || {},
		params: params || {},
		withCredentials: true,
		paramsSerializer : (params)=> new URLSearchParams(params).toString()
	})

	return setInterceptors(instance, null, router, paramData, contentType)
}

// 기존(자바)
