	return createInstance(SERVER_BASE, paramData, params, contentType, headers, responseType)
}

// 파이썬
const pApi = (paramData, params, contentType, headers, responseType) => {
	return createInstance(PYTHON_BASE, paramData, params, contentType, headers, responseType)
}

