import { ref } from 'vue'

// 전역 상태 (Singleton)
const showAlert = ref(false)
const alertTitle = ref('알림')
const alertText = ref('')
const alertCallback = ref(null)

export const useGlobalAlert = () => {
    const openAlert = (text, title = '알림', callback=null) => {
        alertText.value = text
        alertTitle.value = title
        showAlert.value = true
        alertCallback.value = callback
    }

    // 확인 버튼/Escape 등 닫히는 경로와 무관하게 후속 동작을 정확히 한 번만 실행한다.
    const closeAlert = () => {
        showAlert.value = false

        const callback = alertCallback.value
        alertCallback.value = null // 재진입·중복 실행 방지를 위해 먼저 비운다
        if (typeof callback === 'function') callback()
    }

    return {
        showAlert,
        alertTitle,
        alertText,
        alertCallback,
        openAlert,
        closeAlert,
    }
